insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011011', '00000000-0000-4000-a000-000000000101', 1, 0, 'MOSAiC, the Multidisciplinary drifting Observatory for the Study of Arctic Climate, was led by the Alfred Wegener Institute. The research icebreaker Polarstern sailed from Tromsø on 20 September 2019 and the expedition lasted 389 days. 442 experts from 20 nations travelled to the Arctic in phases during the year. Archive note written for DhruvGyani from the linked source page.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011012', '00000000-0000-4000-a000-000000000101', 2, 1, 'Polarstern spent 10 months frozen into the sea ice and drifted 3400 km with it. The team worked for 300 days on the first MOSAiC ice floe and 30 days on a second floe. The drift took the ship to within 156 kilometres of the North Pole. The lowest temperature measured was -42.3 °C, on 10 March 2020.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011013', '00000000-0000-4000-a000-000000000101', 3, 2, 'The team sighted 60 polar bears during the year. 7 icebreakers and research ships supported the expedition, and 247 monitoring stations were set up on the ice, up to 50 km from the ship. The deepest ocean measurement reached 4,297 m and the highest atmospheric measurement reached 36,278 m.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011021', '00000000-0000-4000-a000-000000000102', 1, 0, 'The Arctic Seafloor Expedition ran from 1 July to 10 August 2007, a 40-day cruise aboard the Swedish icebreaker Oden. It went to the Gakkel Ridge in the eastern Arctic Ocean, the northern extension of the Mid-Atlantic Ridge. Archive note written for DhruvGyani from the linked source page.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011022', '00000000-0000-4000-a000-000000000102', 2, 1, 'The team set out to see whether active hydrothermal vents exist on the ridge, to find them, and to learn whether the communities of life around them differ from those elsewhere. They used 2 robotic autonomous underwater vehicles, PUMA and Jaguar, built to be lowered through holes in the sea ice and explore the deep Arctic Ocean.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011031', '00000000-0000-4000-a000-000000000103', 1, 0, 'The Penguins and Lava Flows Expedition ran from 26 November to 23 December 2007 on Ross Island and at Mt. Morning in Antarctica. Penguin biologists David Ainley and Grant Ballard worked alongside geologists Mark Kurz and Adam Soule and graduate student Andrea Burke. Archive note written for DhruvGyani from the linked source page.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011032', '00000000-0000-4000-a000-000000000103', 2, 1, 'The biologists continued a 55-year-long study of Adélie penguins. About 4,000 Adélie penguin pairs and their chicks live at Cape Royds, about 15 miles north of McMurdo Station, and about 100,000 pairs live at Cape Crozier. The geologists studied how lava flows that erupted between 25,000 and 300,000 years ago have weathered, to learn about past climate and the history of the ice sheet.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011041', '00000000-0000-4000-a000-000000000104', 1, 0, 'New Zealand''s International Polar Year Census of Antarctic Marine Life voyage was led by NIWA aboard RV Tangaroa. Voyage TAN0802 left Wellington on 26 January 2008 and returned to Wellington on 21 March 2008. Archive note written for DhruvGyani from the linked source page.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011042', '00000000-0000-4000-a000-000000000104', 2, 1, 'A team of 26 scientists and 18 crew surveyed the Ross Sea and the waters around Scott Island and the Balleny Islands. They collected more than 30,000 specimens using bottom trawls, beam trawls, epibenthic sleds, grabs and plankton nets, in the worst ice conditions documented in the Ross Sea in 30 years.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011051', '00000000-0000-4000-a000-000000000105', 1, 0, 'SAMPLE - internal. Station logistics debrief: fuel handling, generator maintenance schedule and cargo notes. This item is internal and must never be sent to an AI service.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011061', '00000000-0000-4000-a000-000000000106', 1, 0, 'SAMPLE - embargoed. Preliminary snow chemistry results pending peer review. This item is embargoed and must not appear publicly or be sent to an AI service before its release date.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011071', '00000000-0000-4000-a000-000000000107', 1, 0, 'मोज़ेक (MOSAiC) आर्कटिक का एक वर्ष लंबा अभियान था, जिसका नेतृत्व जर्मनी के अल्फ्रेड वेगेनर संस्थान ने किया। अनुसंधान पोत पोलरस्टर्न 20 सितंबर 2019 को ट्रोम्सो से रवाना हुआ और अभियान 389 दिन चला। 20 देशों के 442 विशेषज्ञ इसमें शामिल हुए। यह अभिलेख टिप्पणी अभियान की आधिकारिक वेबसाइट के आधार पर ध्रुवज्ञानी के लिए लिखी गई है।') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011072', '00000000-0000-4000-a000-000000000107', 2, 1, 'पोत 10 महीने समुद्री बर्फ में जमा रहा और बर्फ के साथ 3400 km बहा। सबसे कम तापमान -42.3 °C दर्ज हुआ। टीम ने वर्ष भर में 60 ध्रुवीय भालू देखे।') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011111', '00000000-0000-4000-a000-000000000111', 1, 0, 'Arctic sea-ice extent and area for each September from 1979 to 2025, in million square kilometres, from the NSIDC Sea Ice Index, Version 4. September is the month of the Arctic minimum.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011121', '00000000-0000-4000-a000-000000000112', 1, 0, 'Antarctic sea-ice extent and area for each February from 1979 to 2026, in million square kilometres, from the NSIDC Sea Ice Index, Version 4. February is the month of the Antarctic minimum.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011151', '00000000-0000-4000-a000-000000000115', 1, 0, 'Arctic sea-ice extent and area for each March from 1979 to 2026, in million square kilometres, from the NSIDC Sea Ice Index, Version 4. March is the month of the Arctic winter maximum.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011161', '00000000-0000-4000-a000-000000000116', 1, 0, 'Antarctic sea-ice extent and area for each September from 1979 to 2025, in million square kilometres, from the NSIDC Sea Ice Index, Version 4. September is the month of the Antarctic winter maximum.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011131', '00000000-0000-4000-a000-000000000113', 1, 0, 'External link: National Polar Data Center, hosted by NCPOR. Visit the source site for datasets, metadata and licensing.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011141', '00000000-0000-4000-a000-000000000114', 1, 0, 'External link: Antarctic meteorological data portal, hosted by NCPOR. Visit the source site for data and terms of use.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011171', '00000000-0000-4000-a000-000000000117', 1, 0, 'External link: MOSAiC datasets published by PANGAEA. Visit the source site for the data, DOIs and licences.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011211', '00000000-0000-4000-a000-000000000121', 1, 0, 'Overview of the MOSAiC expedition: Atmosphere. Shupe and co-authors, Elementa: Science of the Anthropocene, volume 10, 2022. Open-access overview paper from the MOSAiC atmosphere team; read it at the DOI link.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011221', '00000000-0000-4000-a000-000000000122', 1, 0, 'Overview of the MOSAiC expedition: Snow and sea ice. Nicolaus and co-authors, Elementa: Science of the Anthropocene, volume 10, 2022. Open-access overview paper from the MOSAiC snow and sea-ice team; read it at the DOI link.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011231', '00000000-0000-4000-a000-000000000123', 1, 0, 'Overview of the MOSAiC expedition: Physical oceanography. Rabe and co-authors, Elementa: Science of the Anthropocene, volume 10, 2022. Open-access overview paper describing a full year of ocean observations during the drift; read it at the DOI link.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011241', '00000000-0000-4000-a000-000000000124', 1, 0, 'External link: NCPOR news post about the comic book Polar Sciences: A Peek into NCPOR. Visit the source site to read it.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011511', '00000000-0000-4000-a000-000000000151', 1, 0, 'Polar Discovery: Live from the Poles is an outreach programme of the Woods Hole Oceanographic Institution, funded by the U.S. National Science Foundation. It followed 5 expeditions: the North Pole Observatory in April 2007, the Arctic Seafloor expedition in July and August 2007, Penguins and Lava Flows in Antarctica in November and December 2007, Greenland''s Glaciers in July and August 2008, and the Bering Sea Ecosystem in April and May 2009. A photographer and a science writer sent daily dispatches and photo essays, and scientists spoke to museum audiences by satellite phone.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011521', '00000000-0000-4000-a000-000000000152', 1, 0, 'External link: MOSAiC education and outreach resources from CIRES at the University of Colorado Boulder, including classroom activities, 360-degree videos and a free online course taught by MOSAiC scientists.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011531', '00000000-0000-4000-a000-000000000153', 1, 0, 'External link: the British Antarctic Survey image and video library. Images are BAS copyright; visit the source site for terms of use.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011581', '00000000-0000-4000-a000-000000000158', 1, 0, 'External link: the British Antarctic Survey map catalogue, produced by its Mapping and Geographic Information Centre.') on conflict do nothing;
