insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011311', '00000000-0000-4000-a000-000000000131', 1, 0, 'Setting up the MOSAiC ice camp beside Polarstern. The ice camp being set up in front of RV Polarstern during leg 1 of the MOSAiC expedition, autumn 2019. Photo: Stefan Hendricks / Alfred Wegener Institute. Licence: CC BY-SA 4.0, via Wikimedia Commons.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011321', '00000000-0000-4000-a000-000000000132', 1, 0, 'Polarstern in the polar night. RV Polarstern lit up in the darkness of the Arctic winter during the MOSAiC drift. Photo: Esther Horvath / Alfred Wegener Institute. Licence: CC BY-SA 3.0 IGO, via Wikimedia Commons.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011331', '00000000-0000-4000-a000-000000000133', 1, 0, 'Polar bears inspect instrument cables at MOSAiC. Polar bears chewing on power cables for field instruments during the MOSAiC expedition, October 2019. Photo: Janek Uin. Licence: CC BY 4.0, via Wikimedia Commons.') on conflict do nothing;
