insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011351', '00000000-0000-4000-a000-000000000135', 1, 0, 'Summer melt ponds on the MOSAiC floe. Surface melt ponds on the ice during the MOSAiC expedition in July 2020, with Polarstern in the distance. Photo: Evgenii Salganik. Licence: CC BY-SA 4.0, via Wikimedia Commons.') on conflict do nothing;
