insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011391', '00000000-0000-4000-a000-000000000139', 1, 0, 'Sverdrup station, Ny-Ålesund — the research village that hosts Himadri. The Sverdrup research station at Ny-Ålesund, Svalbard, on Kongsfjorden. India''s Himadri station is in the same research village. Photo: Harvey Barrison. Licence: CC BY-SA 2.0, via Wikimedia Commons.') on conflict do nothing;
