insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011611', '00000000-0000-4000-a000-000000000161', 1, 0, 'Aurora over Amundsen-Scott South Pole Station. A 25-second exposure under a full moon during the Antarctic night at the South Pole, July 2005. Photo: Chris Danals / National Science Foundation. Licence: Public domain (NSF), via Wikimedia Commons.') on conflict do nothing;
