insert into public.explainers (item_id, level, language, text, citations) values ('00000000-0000-4000-a000-000000000101', 'school', 'en', 'MOSAiC was a big science trip to the Arctic, the icy area around the North Pole [c1]. A ship called Polarstern let itself freeze into the sea ice and floated along with it for 10 months [c2]. It got very cold: the lowest temperature was -42.3 °C [c2]. The team also saw 60 polar bears during the year [c3].', '[{"marker":"c1","chunk_id":"00000000-0000-4000-a000-000000011011","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":1,"quote":"MOSAiC, the Multidisciplinary drifting Observatory for the Study of Arctic Climate, was led by the Alfred Wegener Institute. The research icebreaker Polarstern sailed from Tromsø o"},{"marker":"c2","chunk_id":"00000000-0000-4000-a000-000000011012","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":2,"quote":"Polarstern spent 10 months frozen into the sea ice and drifted 3400 km with it. The team worked for 300 days on the first MOSAiC ice floe and 30 days on a second floe. The drift to"},{"marker":"c3","chunk_id":"00000000-0000-4000-a000-000000011013","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":3,"quote":"The team sighted 60 polar bears during the year. 7 icebreakers and research ships supported the expedition, and 247 monitoring stations were set up on the ice, up to 50 km from the"}]'::jsonb) on conflict (item_id, level, language) do nothing;
insert into public.explainers (item_id, level, language, text, citations) values ('00000000-0000-4000-a000-000000000101', 'college', 'en', 'MOSAiC was a year-long drift expedition led by the Alfred Wegener Institute: Polarstern left Tromsø on 20 September 2019 and the expedition lasted 389 days, with 442 experts from 20 nations taking part [c1]. The ship spent 10 months frozen into the sea ice and drifted 3400 km, coming within 156 kilometres of the North Pole [c2]. 247 monitoring stations were set up on the ice, up to 50 km from the ship [c3].', '[{"marker":"c1","chunk_id":"00000000-0000-4000-a000-000000011011","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":1,"quote":"MOSAiC, the Multidisciplinary drifting Observatory for the Study of Arctic Climate, was led by the Alfred Wegener Institute. The research icebreaker Polarstern sailed from Tromsø o"},{"marker":"c2","chunk_id":"00000000-0000-4000-a000-000000011012","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":2,"quote":"Polarstern spent 10 months frozen into the sea ice and drifted 3400 km with it. The team worked for 300 days on the first MOSAiC ice floe and 30 days on a second floe. The drift to"},{"marker":"c3","chunk_id":"00000000-0000-4000-a000-000000011013","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":3,"quote":"The team sighted 60 polar bears during the year. 7 icebreakers and research ships supported the expedition, and 247 monitoring stations were set up on the ice, up to 50 km from the"}]'::jsonb) on conflict (item_id, level, language) do nothing;
insert into public.explainers (item_id, level, language, text, citations) values ('00000000-0000-4000-a000-000000000101', 'expert', 'en', 'Drift observatory summary: Polarstern departed Tromsø on 20 September 2019; total duration 389 days; 442 participants from 20 nations [c1]. 10 months beset, 3400 km of drift, 300 days on the first floe and 30 days on a second [c2]. Minimum air temperature -42.3 °C on 10 March 2020 [c2]. Distributed network of 247 monitoring stations out to 50 km; deepest ocean measurement 4,297 m and highest atmospheric measurement 36,278 m [c3].', '[{"marker":"c1","chunk_id":"00000000-0000-4000-a000-000000011011","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":1,"quote":"MOSAiC, the Multidisciplinary drifting Observatory for the Study of Arctic Climate, was led by the Alfred Wegener Institute. The research icebreaker Polarstern sailed from Tromsø o"},{"marker":"c2","chunk_id":"00000000-0000-4000-a000-000000011012","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":2,"quote":"Polarstern spent 10 months frozen into the sea ice and drifted 3400 km with it. The team worked for 300 days on the first MOSAiC ice floe and 30 days on a second floe. The drift to"},{"marker":"c3","chunk_id":"00000000-0000-4000-a000-000000011013","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":3,"quote":"The team sighted 60 polar bears during the year. 7 icebreakers and research ships supported the expedition, and 247 monitoring stations were set up on the ice, up to 50 km from the"}]'::jsonb) on conflict (item_id, level, language) do nothing;
insert into public.explainers (item_id, level, language, text, citations) values ('00000000-0000-4000-a000-000000000101', 'school', 'hi', 'मोज़ेक आर्कटिक की बड़ी विज्ञान यात्रा थी [c1]। पोलरस्टर्न नाम का जहाज़ 10 महीने समुद्री बर्फ में जमा रहा और बर्फ के साथ बहता गया [c2]। वहाँ बहुत ठंड थी: सबसे कम तापमान -42.3 °C था [c2]। टीम ने साल भर में 60 ध्रुवीय भालू भी देखे [c3]।', '[{"marker":"c1","chunk_id":"00000000-0000-4000-a000-000000011011","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":1,"quote":"MOSAiC, the Multidisciplinary drifting Observatory for the Study of Arctic Climate, was led by the Alfred Wegener Institute. The research icebreaker Polarstern sailed from Tromsø o"},{"marker":"c2","chunk_id":"00000000-0000-4000-a000-000000011012","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":2,"quote":"Polarstern spent 10 months frozen into the sea ice and drifted 3400 km with it. The team worked for 300 days on the first MOSAiC ice floe and 30 days on a second floe. The drift to"},{"marker":"c3","chunk_id":"00000000-0000-4000-a000-000000011013","item_id":"00000000-0000-4000-a000-000000000101","item_title":"MOSAiC in numbers — archive note","page_no":3,"quote":"The team sighted 60 polar bears during the year. 7 icebreakers and research ships supported the expedition, and 247 monitoring stations were set up on the ice, up to 50 km from the"}]'::jsonb) on conflict (item_id, level, language) do nothing;
